// on this path stays unpriced/unknown, never zero.

import raider.core.{ModelBackend, Program, RaiderError, RequestMessage, Task, ToolRegistry}
import raider.runtime.admission.Admission
import raider.runtime.budget.{BudgetLimits, CostEstimate}
import raider.runtime.loop.AgentLoop
import raider.tools.CodingToolset
import zio.ZIO
import zio.json.*

object Cwf_e01:

  /** Input boundary (ADR-033 §6.6): validated JSON decoding INSIDE the String
  * boundary. `workspace` is the per-run fresh copy; the nested task params
  * are the externalized task parameters read at RUN time — a second
  * task/workspace input needs no edit and no regeneration.
  */
  final case class TaskParams(targetPath: String, summary: String)

  object TaskParams:
    given zio.json.JsonCodec[TaskParams] = zio.json.DeriveJsonCodec.gen

  final case class Input(schemaVersion: Int, workspace: String, task: TaskParams)

  object Input:
    given zio.json.JsonCodec[Input] = zio.json.DeriveJsonCodec.gen

  // ---- editable parameters (the meaningful-edit surface, ADR-033 §6.5) ----
  // EDIT THESE CONSTANTS to change behavior WITHOUT regenerating; recompile
  // only. The prompt template carries {workspace} {targetPath} {task}
  // placeholders substituted from the input at run time.

  val promptTemplate: String =
    "Task: VERIFIER-INTENT-9d21: publish the module marker now; PUBLISH-TARGET: marker.txt\nRefinement: create only the publish target file and nothing else\nRefinement: verify the publish target exists before reporting done\n\nRun in the workspace {workspace}.\nTask input: {task}\nTarget path: {targetPath}"

  // Named trusted checks (ADR-033 §4.1): validated argv, executed WITHOUT a
  // shell in the workspace. Model text can never add or alter a check —
  // checks exist only here; the input JSON can never inject one.

  val checkMarker: List[String] = List("/bin/test", "-f", "marker.txt")

  val trustedChecks: List[(String, List[String])] = List(
    ("marker", checkMarker),
  )

  // Bound of the ONE sequential agent stage (ADR-033 §4.1); must stay >= 1.
  val maxRounds: Int = 12

  // Per-check wall bound in seconds (bounded work; the coding toolset's
  // process-tool default).
  val checkTimeoutSeconds: Int = 120

  // Provider binding (non-secret references; credentials stay env/helper
  // references and never appear in this file).
  val providerKind: String = "openai-compatible"
  val baseUrl: String = "http://127.0.0.1:49403/v1"

  val modelName: String = "verifier-model-e01"

  /** Explicit launch services (ADR-029 §3.1 rule 2): backend, tools,
  * admission and limits are constructor arguments, never globals.
  */
  final case class Launch(
      backend: ModelBackend,
      tools: ToolRegistry,
      admission: Admission,
      limits: BudgetLimits
  )

  // ---- launch construction SEAM (LauncherTemplate.ExplicitAssembly) ----
  // Explicit assembly over public runtime parts: credentials resolved from
  // CURRENT env (typed auth failure, no hidden fallback — ADR-029 H7), coding
  // tools rooted at the input workspace, validated limits, ONE Admission and
  // ledger for this run (D3: one root/admission/ledger per run; the agent
  // stage creates its loop root below). No Runtime.default in this path; the
  // first network call happens only when the agent stage runs.

  private def credentialProvider: String = providerKind match
    case "openai-compatible"    => "openai"
    case "anthropic-compatible" => "anthropic"
    case other                  => other

  private def buildBackend(keyOpt: Option[String]): Task[ModelBackend] =
    providerKind match
      case "openai-compatible" =>
        keyOpt match
          case None =>
            Task.fail(
              RaiderError.ProviderAuth(
                "no credential for " + providerKind +
                  ": set RAIDER_API_KEY or RAIDER_API_KEY_CMD"
              )
            )
          case Some(key) =>
            Task(
              raider.provider.chat.stream.OpenAIChatStreamingBackend.make(
                raider.provider.chat.OpenAIChatBackend.Config.make(
                  baseUrl,
                  key,
                  callTimeoutMs = 300000L
                )
              )
            )
      case "anthropic-compatible" =>
        keyOpt match
          case None =>
            Task.fail(
              RaiderError.ProviderAuth(
                "no credential for " + providerKind +
                  ": set RAIDER_API_KEY or RAIDER_API_KEY_CMD"
              )
            )
          case Some(key) =>
            Task(
              raider.provider.anthropic.AnthropicMessagesBackend.make(
                raider.provider.anthropic.AnthropicMessagesBackend.Config
                  .make(baseUrl, key, callTimeoutMs = 300000L),
                streaming = true
              )
            )
      case other =>
        Task.fail(
          RaiderError.Configuration(
            "unsupported providerKind: " + other +
              "; supported: openai-compatible, anthropic-compatible"
          )
        )

  /** Builds the launch services for THIS run (D1/D3): construction
  * validates config and allocates admission primitives but performs no
  * network call and starts no agent work (D1 rule 1).
  */
  def buildLaunch(input: Input): Task[Launch] =
    Task(
      ZIO.fromEither(
        raider.cli.run.Credentials.resolve(credentialProvider)
      )
    ).flatMap { keyOpt =>
      buildBackend(keyOpt).flatMap { backend =>
        Task(
          for
            tools <- CodingToolset
              .make(input.workspace)
              .flatMap(ts => ZIO.fromEither(ts.registry))
            limits <- ZIO.fromEither(
              BudgetLimits.make(maxAttempts = maxRounds)
            )
            admission <- Admission.make(Right(limits))
          yield Launch(backend, tools, admission, limits)
        )
      }
    }

  // ---- the definition (ADR-033 §6.3) ----
  // Building any of the values below dispatches NOTHING (API-03): the
  // workflow is a lazy Program[String, String]; only the launcher runs it.

  /** Validated decoding INSIDE the String boundary (schema-version gate,
  * §6.6), then workspace validation (exists, is a directory, not a
  * symlink). Typed failure, never a throw across the boundary.
  */
  def decodeOrRefuse(raw: String): Task[Input] =
    Task(
      ZIO
        .fromEither(raw.fromJson[Input])
        .mapError(err =>
          RaiderError.InputValidation(
            "CWF-input: invalid input JSON: " + err
          )
        )
        .flatMap { input =>
          if input.schemaVersion == 1 then ZIO.succeed(input)
          else
            ZIO.fail(
              RaiderError.InputValidation(
                "CWF-input: unsupported input schemaVersion " +
                  input.schemaVersion + " (expected 1)"
              )
            )
        }
    ).flatMap(input => validateWorkspace(input).map(_ => input))

  def validateWorkspace(input: Input): Task[Unit] =
    Task(
      ZIO.attemptBlocking {
        val p = java.nio.file.Paths.get(input.workspace)
        if !p.isAbsolute then Left("workspace path must be absolute")
        else if !java.nio.file.Files.isDirectory(p) then
          Left("workspace must be an existing directory: " + input.workspace)
        else if java.nio.file.Files.isSymbolicLink(p) then
          Left("workspace must not be a symlink: " + input.workspace)
        else Right(())
      }.mapError(t =>
        RaiderError.InputValidation(
          "CWF-input: workspace validation failed: " + String.valueOf(t)
        )
      ).flatMap {
        case Right(()) => ZIO.unit
        case Left(msg) =>
          ZIO.fail(RaiderError.InputValidation("CWF-input: " + msg))
      }
    )

  /** Substitutes the run's externalized parameters into the editable
  * template. Purely textual — the input values are DATA and are never
  * interpreted as commands (ADR-033 §8).
  */
  def renderPrompt(template: String, input: Input): String =
    template
      .replace("{workspace}", input.workspace)
      .replace("{targetPath}", input.task.targetPath)
      .replace("{task}", input.task.summary)

  /** The exported workflow: validated input, ONE bounded sequential
  * agent stage over the explicit services, output validation, then the
  * named trusted checks on the NEW workspace (a failed check fails the
  * run — ci-runtime §7; R9).
  */
  def workflow(launch: Launch): Program[String, String] =
    Program.fromFunction("cwf_e01-workflow"): rawInput =>
      for
        input <- decodeOrRefuse(rawInput)
        prompt = renderPrompt(promptTemplate, input)
        answer <- agentStage(launch, prompt)
        validated <- validateOutput(answer)
        _ <- runAllChecks(input)
      yield report(validated, input)

  /** ONE sequential bounded agent stage (ADR-033 §4.1): model+tool
  * rounds through the existing AgentLoop over the explicit services;
  * bounded by `maxRounds` and re-validated by current limits at run
  * time; no parallelism, no delegation, no second scheduler (D3/D4).
  */
  private def agentStage(launch: Launch, prompt: String): Task[String] =
    Task(
      for
        root <- ZIO.succeed(AgentLoop.newRoot())
        loop = AgentLoop(
          backend = launch.backend,
          tools = launch.tools,
          model = modelName,
          admission = launch.admission,
          root = root,
          attemptEstimate = CostEstimate.Unknown
        )
        finalText <- loop.runText(
          List(RequestMessage("user", prompt)),
          launch.limits,
          maxRounds
        )
      yield finalText
    )

  /** Output validation: the recorded chat answer is never replayed —
  * the stage's own fresh answer must be non-empty and marker-free.
  */
  private def validateOutput(answer: String): Task[String] =
    if answer.trim.isEmpty then
      Task.fail(
        RaiderError.OutputValidation(
          "agent stage returned an empty answer"
        )
      )
    else if answer.contains(AgentLoop.InternalMarker) then
      Task.fail(
        RaiderError.OutputValidation(
          "agent answer carries the internal marker; refusing to publish"
        )
      )
    else Task.succeed(answer)

  /** All named checks in order (ADR-033 §4.1 SuccessPolicy: checks must
  * pass on the NEW workspace; "the agent said done" is never a
  * verdict).
  */
  private def runAllChecks(input: Input): Task[Unit] =
    Task(
      ZIO.foreach(trustedChecks) { case (name, argv) =>
        Task.zio(runNamedCheck(input, name, argv))
      }.unit
    )

  /** One named check: argv runs WITHOUT a shell in the workspace
  * directory, bounded wait, output inherited. The argv comes ONLY from
  * the editable constants above — never from the input JSON
  * (text-is-data, §8). Nonzero exit is a typed failed run (R9): a
  * failed check stays failed.
  */
  private def runNamedCheck(
      input: Input,
      name: String,
      argv: List[String]
  ): Task[Unit] =
    Task(
      ZIO
        .attemptBlocking {
          val proc = new ProcessBuilder(argv*)
            .directory(java.nio.file.Paths.get(input.workspace).toFile)
            .redirectErrorStream(true)
            .redirectOutput(ProcessBuilder.Redirect.INHERIT)
            .start()
          if proc.waitFor(
              checkTimeoutSeconds.toLong,
              java.util.concurrent.TimeUnit.SECONDS
            )
          then Right(proc.exitValue()): Either[String, Int]
          else
            proc.destroyForcibly()
            Left(
              "exceeded the " + checkTimeoutSeconds +
                "s bound and was destroyed"
            ): Either[String, Int]
        }
        .mapError(t =>
          RaiderError.OutputValidation(
            "check '" + name + "' could not start: " +
              String.valueOf(t)
          )
        )
        .flatMap {
          case Right(0) => ZIO.unit
          case Right(code) =>
            ZIO.fail(
              RaiderError.OutputValidation(
                "check '" + name + "' failed with exit code " + code
              )
            )
          case Left(reason) =>
            ZIO.fail(
              RaiderError.DeadlineExceeded(
                "check '" + name + "' " + reason
              )
            )
        }
    )

  /** Deterministic textual report (the Program output). */
  private def report(answer: String, input: Input): String =
    "checks passed: " + trustedChecks.map((name, _) => name)
      .mkString(", ") + "; target=" + input.task.targetPath + "\n" + answer

  // ---- launcher (Option L, ADR-033 §3/§6.3) ----

  /** Reads the externalized input (§6.6). Missing/unreadable input is
  * a typed failure BEFORE any dispatch.
  */
  def readInputFile(path: String): Task[String] =
    Task(
      ZIO.attemptBlocking(
        java.nio.file.Files.readString(
          java.nio.file.Paths.get(path),
          java.nio.charset.StandardCharsets.UTF_8
        )
      ).mapError(t =>
        RaiderError.InputValidation(
          "CWF-input: cannot read input file '" + path + "': " +
            String.valueOf(t)
        )
      )
    )

  /** One launcher run: read input -> decode -> build the launch
  * services -> run the workflow. Every step is typed; nothing
  * dispatches before the agent stage. Build identity of this source
  * lives in cwf_e01-manifest.json; a manual edit
  * invalidates earlier result claims (CWF-D02, wired by RAI-155.d).
  */
  def runOnce(inputPath: String): Task[Unit] =
    for
      raw <- readInputFile(inputPath)
      input <- decodeOrRefuse(raw)
      launch <- buildLaunch(input)
      result <- Task(Task.zio(workflow(launch)(raw)))
      _ <- Task(ZIO.succeed(println(result)))
    yield ()

  /** Console adapter (D4): the ONLY place a blocking interpreter run is
  * allowed; typed failures become a truthful nonzero exit with
  * "raider CODE: detail" on stderr. Artifact/exit-table/SIGTERM
  * wiring is the RAI-155.d launcher discipline (§7).
  */
  def runLauncher(args: Seq[String]): ZIO[Any, Nothing, Int] =
    val inputPath =
      if args.isEmpty then "cwf_e01.input.json" else args.head
    Task.zio(runOnce(inputPath)).either.map {
      case Right(()) => 0
      case Left(err) =>
        System.err.println("raider " + err.code + ": " + err.detail)
        1
    }

@main def runCwf_e01(args: String*): Unit =
  // Option L launcher: explicit main binding CURRENT env/config at run
  // time; authority is never inherited from the exporting chat session
  // (ADR-033 §7). Exit 0 = checks green on the new workspace; nonzero =
  // typed failure.
  zio.Unsafe.unsafe { implicit u =>
    val code = zio.Runtime.default.unsafe
      .run(Cwf_e01.runLauncher(args))
      .getOrThrow()
    if code != 0 then sys.exit(code)
  }
